  // locationSetting.ts
  DATA_LOCATION_WARNING_TO_NOTE: "\u0411\u0423\u0414\u042C\u0422\u0415 \u041E\u0421\u0422\u041E\u0420\u041E\u0416\u041D\u042B!!!\n\u0415\u0441\u043B\u0438 \u0432\u044B \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 \u044D\u0442\u043E, \u0432\u0441\u0435 \u0432\u0430\u0448\u0438 \u0434\u0430\u043D\u043D\u044B\u0435 \u043F\u043B\u0430\u043D\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u044F \u0438\u0437 `tracked_files.json` \u0431\u0443\u0434\u0443\u0442 \u043A\u043E\u043D\u0432\u0435\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u044B \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0438, \u0447\u0442\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442 \u043C\u043D\u043E\u0436\u0435\u0441\u0442\u0432\u043E \u0432\u0430\u0448\u0438\u0445 \u0444\u0430\u0439\u043B\u043E\u0432 \u0437\u0430\u043C\u0435\u0442\u043E\u043A \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E.\n\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u0443\u0431\u0435\u0434\u0438\u0442\u0435\u0441\u044C, \u0447\u0442\u043E \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0442\u0435\u0433\u043E\u0432 \u043A\u0430\u0440\u0442\u043E\u0447\u0435\u043A \u0438 \u0437\u0430\u043C\u0435\u0442\u043E\u043A \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0442 \u0442\u043E\u043C\u0443, \u0447\u0442\u043E \u0432\u044B \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0435.",
  DATA_LOCATION_WARNING_OTHER_ALGO: "\u0435\u0441\u043B\u0438 \u0432\u044B \u0445\u043E\u0442\u0438\u0442\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0442\u044C \u0434\u0430\u043D\u043D\u044B\u0435 \u0432 \u0444\u0430\u0439\u043B\u0435 \u0437\u0430\u043C\u0435\u0442\u043A\u0438, \u0432\u044B **\u0434\u043E\u043B\u0436\u043D\u044B** \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0430\u043B\u0433\u043E\u0440\u0438\u0442\u043C \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E.",
  DATA_LOCATION_WARNING_TO_TRACKED: "\u0411\u0423\u0414\u042C\u0422\u0415 \u041E\u0421\u0422\u041E\u0420\u041E\u0416\u041D\u042B!!!\n\u0415\u0441\u043B\u0438 \u0432\u044B \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 \u044D\u0442\u043E, \u0432\u0441\u0435 \u0432\u0430\u0448\u0438 \u0434\u0430\u043D\u043D\u044B\u0435 \u043F\u043B\u0430\u043D\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u044F \u0438\u0437 \u0437\u0430\u043C\u0435\u0442\u043E\u043A (\u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0431\u0443\u0434\u0443\u0442 \u0443\u0434\u0430\u043B\u0435\u043D\u044B \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E) \u0431\u0443\u0434\u0443\u0442 \u043A\u043E\u043D\u0432\u0435\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u044B \u0412 `tracked_files.json`.",
  // trackSetting.ts
  UNTRACK_WITH_REVIEWTAG_DESC: "\u041F\u0440\u0438 \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u0438 \u0442\u0435\u0433\u0430 \u043F\u043E\u0432\u0442\u043E\u0440\u0435\u043D\u0438\u044F \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0435 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u043D\u043E \u043E\u0442\u043C\u0435\u043D\u0438\u0442\u044C \u043E\u0442\u0441\u043B\u0435\u0436\u0438\u0432\u0430\u043D\u0438\u0435, \u0447\u0442\u043E\u0431\u044B \u0437\u0430\u043C\u0435\u0442\u043A\u0430 \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u043B\u0430\u0441\u044C<br><b>\u0432\u043A\u043B\u044E\u0447\u0435\u043D\u043E</b>: \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u043D\u0430\u044F \u043E\u043F\u0435\u0440\u0430\u0446\u0438\u044F \u043E\u0442\u043C\u0435\u043D\u044B \u043E\u0442\u0441\u043B\u0435\u0436\u0438\u0432\u0430\u043D\u0438\u044F;<br><b>\u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u043E</b>: \u041F\u043E\u0441\u043B\u0435 \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u044F \u0442\u0435\u0433\u0430 \u043F\u043E\u0432\u0442\u043E\u0440\u0435\u043D\u0438\u044F \u043D\u0443\u0436\u043D\u043E \u043E\u0442\u043C\u0435\u043D\u0438\u0442\u044C \u043E\u0442\u0441\u043B\u0435\u0436\u0438\u0432\u0430\u043D\u0438\u0435 \u0435\u0449\u0435 \u0440\u0430\u0437, \u043F\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043C \u0437\u0430\u043C\u0435\u0442\u043A\u0430 \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u043D\u0435\u0442 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0442\u044C\u0441\u044F. (\u043A\u0430\u043A \u0432 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0439 \u0432\u0435\u0440\u0441\u0438\u0438)",
