// src/algorithms/supermemo.ts
var import_deepcopy4 = __toESM(require_deepcopy());
var Sm2Options2 = ["Blackout", "Incorrect", "Incorrect (Easy)", "Hard", "Good", "Easy"];
var Sm2Algorithm = class extends SrsAlgorithm {
  defaultSettings() {
    return new AnkiAlgorithm().defaultSettings();
  }
  defaultData() {
    return {
      ease: 2.5,
      lastInterval: 0,
      iteration: 1
    };
  }
  srsOptions() {
    return Sm2Options2;
  }
  calcAllOptsIntervals(item) {
    const intvls = [];
    this.srsOptions().forEach((opt, _ind) => {
      const itemCopy = (0, import_deepcopy4.default)(item);
      const result = this.onSelection(itemCopy, opt, false);
      const intvl = Math.round(result.nextReview / DateUtils.DAYS_TO_MILLIS * 100) / 100;
      intvls.push(intvl);
    });
    return intvls;
  }
  onSelection(item, optionStr, repeat) {
    const data = item.data;
    console.log("item.data:", item.data);
    const interval = function(n) {
      if (n === 1) {
        return 1;
      } else if (n === 2) {
        return 6;
      } else {
        return Math.round(data.lastInterval * data.ease);
      }
    };
    const q = Sm2Options2.indexOf(optionStr);
    if (repeat) {
      if (q < 3) {
        return { correct: false, nextReview: -1 };
      } else {
        return { correct: true, nextReview: -1 };
      }
    }
    if (q < 3) {
      data.iteration = 1;
      const nextReview = interval(data.iteration);
      data.lastInterval = nextReview;
      return {
        correct: false,
        nextReview: nextReview * DateUtils.DAYS_TO_MILLIS
      };
    } else {
      const nextReview = interval(data.iteration);
      data.iteration += 1;
      data.ease = data.ease + (0.1 - (5 - q) * (0.08 + (5 - q) * 0.02));
      if (data.ease < 1.3) {
        data.ease = 1.3;
      }
      data.ease = MiscUtils.fixed(data.ease, 3);
      data.lastInterval = nextReview;
      return {
        correct: true,
        nextReview: nextReview * DateUtils.DAYS_TO_MILLIS
      };
    }
  }
  importer(fromAlgo, items) {
    const anki = new AnkiAlgorithm();
    anki.updateSettings(this.settings);
    anki.importer(fromAlgo, items);
  }
  displaySettings(containerEl, update) {
    containerEl.createDiv().innerHTML = t("SM2_ALGORITHM_DESC");
    const anki = new AnkiAlgorithm();
    anki.updateSettings(this.settings);
    anki.displaySettings(containerEl, (settings, refresh) => {
      update(this.settings = settings, refresh);
    });
  }
};

// src/algorithms/algorithms_switch.ts
var algorithms = {
  Default: new DefaultAlgorithm(),
  Anki: new AnkiAlgorithm(),
  Fsrs: new FsrsAlgorithm(),
  SM2: new Sm2Algorithm()
};
async function algorithmSwitchData(plugin, fromAlgo, toAlgo) {
  const store = plugin.store;
  const items = store.data.items;
  const old_path = store.dataPath;
  const bak_path = old_path + "." + fromAlgo + ".bak";
  await store.save(bak_path);
  await store.pruneData();
  await store.verifyItems();
  const fromTo = " from " + fromAlgo + " to: " + toAlgo;
  try {
    const algo = algorithms[toAlgo];
    algo.updateSettings(plugin.data.settings.algorithmSettings[toAlgo]);
    algo.importer(fromAlgo, items);
    if (toAlgo === "Fsrs" /* Fsrs */) {
      store.data.items.find((item) => {
        if (Object.prototype.hasOwnProperty.call(item.data, "ease")) {
          throw new Error("conv to fsrs failed");
        }
      });
    } else if (fromAlgo === "Fsrs" /* Fsrs */) {
      store.data.items.find((item) => {
        if (Object.prototype.hasOwnProperty.call(item.data, "state")) {
          throw new Error("conv to fsrs failed");
        }
      });
    }
    await store.save();
    const msg = fromTo + t("ALGORITHM_SWITCH_SUCCESS");
    new import_obsidian9.Notice(msg);
    console.debug(msg);
    return true;
  } catch (error) {
    await store.load(bak_path);
    new import_obsidian9.Notice(error + fromTo + t("ALGORITHM_SWITCH_FAILED"));
    console.log(error);
    return false;
  }
}

