var TextInputSuggest = class {
  constructor(inputEl) {
    this.inputEl = inputEl;
    this.scope = new import_obsidian15.Scope();
    this.suggestEl = createDiv("suggestion-container");
    const suggestion = this.suggestEl.createDiv("suggestion");
    this.suggest = new Suggest(this, suggestion, this.scope);
    this.scope.register([], "Escape", this.close.bind(this));
    this.inputEl.addEventListener("input", this.onInputChanged.bind(this));
    this.inputEl.addEventListener("focus", this.onInputChanged.bind(this));
    this.inputEl.addEventListener("blur", this.close.bind(this));
    this.suggestEl.on("mousedown", ".suggestion-container", (event) => {
      event.preventDefault();
    });
  }
  onInputChanged() {
    const inputStr = this.inputEl.value;
    const suggestions = this.getSuggestions(inputStr);
    if (!suggestions) {
      this.close();
      return;
    }
    if (suggestions.length > 0) {
      this.suggest.setSuggestions(suggestions);
      this.open(Iadapter.instance.app.dom.appContainerEl, this.inputEl);
    } else {
      this.close();
    }
  }
  open(container, inputEl) {
    Iadapter.instance.app.keymap.pushScope(this.scope);
    container.appendChild(this.suggestEl);
    this.popper = createPopper(inputEl, this.suggestEl, {
      placement: "bottom-start",
      modifiers: [
        {
          name: "sameWidth",
          enabled: true,
          fn: ({ state, instance: instance2 }) => {
            const targetWidth = `${state.rects.reference.width}px`;
            if (state.styles.popper.width === targetWidth) {
              return;
            }
            state.styles.popper.width = targetWidth;
            instance2.update();
          },
          phase: "beforeWrite",
          requires: ["computeStyles"]
        }
      ]
    });
  }
  close() {
    Iadapter.instance.app.keymap.popScope(this.scope);
    this.suggest.setSuggestions([]);
    if (this.popper)
      this.popper.destroy();
    this.suggestEl.detach();
  }
};

// src/suggesters/FolderSuggester.ts
var FolderSuggest = class extends TextInputSuggest {
  getSuggestions(inputStr) {
    const abstractFiles = Iadapter.instance.vault.getAllLoadedFiles();
    const folders = [];
    const lowerCaseInputStr = inputStr.toLowerCase();
    abstractFiles.forEach((folder) => {
      if (folder instanceof import_obsidian16.TFolder && folder.path.toLowerCase().includes(lowerCaseInputStr)) {
        folders.push(folder);
      }
    });
    return folders;
  }
  renderSuggestion(file, el) {
    el.setText(file.path);
  }
  selectSuggestion(file) {
    this.inputEl.value = file.path;
    this.inputEl.trigger("input");
    this.close();
  }
};

// src/settings/locationSetting.ts
function addDataLocationSettings(containerEl, plugin) {
  containerEl.empty();
  const settings = plugin.data.settings;
  const locSwitch = new LocationSwitch(plugin, settings);
  const desc_toNote = t("DATA_LOCATION_WARNING_TO_NOTE");
  const desc_toNote_otherAlgo = t("DATA_LOCATION_WARNING_OTHER_ALGO");
  const desc_toTrackedFiles = t("DATA_LOCATION_WARNING_TO_TRACKED");
  new import_obsidian17.Setting(containerEl).setName(t("DATA_LOC")).setDesc(t("DATA_LOC_DESC")).addDropdown((dropdown) => {
    const localizedMap = getLocalizedLocationMap();
    Object.entries(localizedMap).forEach(([localizedName, dataLocation]) => {
      dropdown.addOption(dataLocation, localizedName);
    });
    dropdown.setValue(plugin.data.settings.dataLocation);
    dropdown.onChange(async (val) => {
      const loc = val;
      await plugin.sync();
      const noteStats = (0, import_deepcopy6.default)(plugin.noteStats);
      const cardStats = (0, import_deepcopy6.default)(plugin.cardStats);
      let confirmP;
      if (loc === "Save On Note File" /* SaveOnNoteFile */) {
        if (settings.algorithm === "Default" /* Default */) {
          await locSwitch.converteTrackfileToNoteSched(true);
          confirmP = new Promise(function(resolve2) {
            new ConfirmModal(
              plugin,
              desc_toNote + "### review Notes\n" + locSwitch.createTable(
                locSwitch.beforenoteStats,
                locSwitch.afternoteStats
              ) + "\n---\n### flashcards\n" + locSwitch.createTable(
                locSwitch.beforecardStats,
                locSwitch.aftercardStats
              ),
              async (confirm) => {
                if (confirm) {
                  await locSwitch.converteTrackfileToNoteSched();
                  plugin.data.settings.dataLocation = loc;
                  locSwitch.moveStoreLocation();
                  plugin.data.settings.customFolder = locSwitch.getStorePath();
                  resolve2(true);
                }
              }
            ).open();
          });
        } else {
          new ConfirmModal(plugin, desc_toNote_otherAlgo, () => {
            dropdown.setValue(plugin.data.settings.dataLocation);
          }).open();
        }
      } else if (settings.dataLocation === "Save On Note File" /* SaveOnNoteFile */) {
        await locSwitch.converteNoteSchedToTrackfile(true, loc);
        confirmP = new Promise(function(resolve2) {
          new ConfirmModal(
            plugin,
            desc_toTrackedFiles + "### review Notes\n" + locSwitch.createTable(
              locSwitch.beforenoteStats,
              locSwitch.afternoteStats
            ) + "\n---\n### flashcards\n" + locSwitch.createTable(
              locSwitch.beforecardStats,
              locSwitch.aftercardStats
            ),
            async (confirm) => {
              if (confirm) {
                await plugin.sync();
                plugin.data.settings.dataLocation = loc;
                await locSwitch.moveStoreLocation();
                plugin.data.settings.customFolder = locSwitch.getStorePath();
                await locSwitch.converteNoteSchedToTrackfile();
                resolve2(true);
              }
            }
          ).open();
        });
      } else {
        plugin.data.settings.dataLocation = loc;
        await locSwitch.moveStoreLocation();
        plugin.data.settings.customFolder = locSwitch.getStorePath();
        await plugin.savePluginData();
      }
      dropdown.setValue(plugin.data.settings.dataLocation);
      if (await confirmP) {
        dropdown.setValue(plugin.data.settings.dataLocation);
        await plugin.savePluginData();
        await plugin.app.plugins.disablePlugin(plugin.manifest.id);
        await plugin.app.plugins.enablePlugin(plugin.manifest.id);
        console.debug(t("LOCATION_CHANGE_FINISHED"));
        await plugin.sync();
        locSwitch.resultCheck(noteStats, cardStats, plugin.noteStats, plugin.cardStats);
      }
      addDataLocationSettings(containerEl, plugin);
    });
  });
  if (settings.dataLocation === "In the folder specified below" /* SpecifiedFolder */) {
    settings.customFolder = plugin.store.dataPath;
    addSpecifiedFolderSetting(containerEl, plugin);
  }
}
function addSpecifiedFolderSetting(containerEl, plugin) {
  const settings = plugin.data.settings;
  const locSwitch = new LocationSwitch(plugin, settings);
  const fder_index = plugin.data.settings.customFolder.lastIndexOf("/");
  let cusFolder = plugin.data.settings.customFolder.substring(0, fder_index);
  const cusFilename = plugin.data.settings.customFolder.substring(fder_index + 1);
  new import_obsidian17.Setting(containerEl).setName(t("DATA_FOLDER")).addSearch((cb) => {
    new FolderSuggest(cb.inputEl);
    cb.setPlaceholder(t("FOLDER_PLACEHOLDER")).setValue(cusFolder).onChange((new_folder) => {
      cusFolder = new_folder;
      cb.setValue(cusFolder);
    });
  }).addButton(
    (btn) => btn.setButtonText(t("SAVE_BUTTON")).setCta().onClick(async () => {
      plugin.data.settings.customFolder = cusFolder + "/" + cusFilename;
      await locSwitch.moveStoreLocation();
      await plugin.savePluginData();
    })
  );
}

