// src/settings/mixQueueSetting.ts
function addmixQueueSetting(containerEl, plugin) {
  const settings = plugin.data.settings;
  new import_obsidian21.Setting(containerEl).setName(t("MIX_QUEUE")).setDesc(t("MIX_QUEUE_DESC")).addSlider(
    (slider) => slider.setLimits(1, 7, 1).setValue(settings.mixDue + settings.mixNew).setDynamicTooltip().onChange(async (value) => {
      applySettingsUpdate3(async () => {
        settings.mixDue = Math.min(value, settings.mixDue);
        settings.mixNew = value - settings.mixDue;
        await update();
      });
    })
  ).addSlider(
    (slider) => slider.setLimits(0, Math.min(7, settings.mixDue + settings.mixNew), 1).setValue(settings.mixDue).setDynamicTooltip().onChange((value) => {
      applySettingsUpdate3(async () => {
        settings.mixDue = value;
        await update();
      });
    })
  ).addExtraButton((button) => {
    button.setIcon("reset").setTooltip(t("RESET_DEFAULT")).onClick(async () => {
      applySettingsUpdate3(async () => {
        settings.mixDue = DEFAULT_SETTINGS.mixDue;
        settings.mixNew = DEFAULT_SETTINGS.mixNew;
        await update();
      });
    });
  });
  async function update() {
    await plugin.savePluginData();
    plugin.settingTab.display();
    mixQueSet_exports.create(settings.mixDue, settings.mixNew, settings.mixCard, settings.mixNote);
  }
}

