// src/settings/algorithmSetting.ts
var DEFAULT_responseOptionBtnsText = {
  Default: [t("RESET"), t("HARD"), t("GOOD"), t("EASY")],
  Fsrs: [t("RESET"), t("HARD"), t("GOOD"), t("EASY")],
  Anki: [t("RESET"), t("HARD"), t("GOOD"), t("EASY")],
  SM2: ["Blackout", "Incorrect", "Incorrect (Easy)", t("HARD"), t("GOOD"), t("EASY")]
};
function addAlgorithmSetting(containerEl, plugin) {
  const settings = plugin.data.settings;
  const desc = createFragment((frag) => {
    frag.createDiv().innerHTML = t("ALGORITHMS_DESC");
  });
  new import_obsidian25.Setting(containerEl).setName(t("ALGORITHM")).setDesc(desc).addDropdown((dropdown) => {
    Object.keys(algorithms).forEach((val) => {
      dropdown.addOption(val, val);
    });
    const oldAlgo = plugin.data.settings.algorithm;
    dropdown.setValue(plugin.data.settings.algorithm);
    dropdown.onChange((newValue) => {
      if (settings.dataLocation === "Save On Note File" /* SaveOnNoteFile */ && newValue !== "Default" /* Default */) {
        new ConfirmModal(
          plugin,
          "if you want to use " + newValue + " Algorithm, you **can't ** save data on notefile.",
          () => {
            dropdown.setValue(settings.algorithm);
          }
        ).open();
        return;
      }
      new ConfirmModal(plugin, t("ALGORITHMS_CONFIRM"), async (confirmed) => {
        if (confirmed) {
          const result = await algorithmSwitchData(
            plugin,
            oldAlgo,
            newValue
          );
          if (!result) {
            dropdown.setValue(settings.algorithm);
            return;
          }
          settings.algorithm = newValue;
          await plugin.savePluginData();
          await plugin.app.plugins.disablePlugin(plugin.manifest.id);
          await plugin.app.plugins.enablePlugin(plugin.manifest.id);
        } else {
          dropdown.setValue(settings.algorithm);
        }
      }).open();
    });
  });
}
function addAlgorithmSpecificDisplaySetting(containerEl, plugin) {
  const update = async (settings, refresh) => {
    plugin.data.settings.algorithmSettings[plugin.data.settings.algorithm] = settings;
    await plugin.savePluginData();
    if (refresh)
      plugin.algorithm.displaySettings(containerEl, update);
  };
  plugin.algorithm.displaySettings(containerEl.createDiv(), update);
}
function addResponseButtonTextSetting(containerEl, plugin) {
  containerEl.empty();
  const options = plugin.algorithm.srsOptions();
  const settings = plugin.data.settings;
  const algo = settings.algorithm;
  const btnText = settings.responseOptionBtnsText;
  if (btnText[algo] == null) {
    btnText[algo] = [];
    options.forEach((opt, ind) => btnText[algo][ind] = t(opt.toUpperCase()));
  }
  options.forEach((opt, ind) => {
    const btnTextEl = new import_obsidian25.Setting(containerEl).setName(t("FLASHCARD_" + opt.toUpperCase() + "_LABEL")).setDesc(t("FLASHCARD_" + opt.toUpperCase() + "_DESC"));
    btnTextEl.addText(
      (text) => text.setValue(btnText[algo][ind]).onChange((value) => {
        applySettingsUpdate3(() => {
          btnText[algo][ind] = value;
          plugin.savePluginData();
        });
      })
    );
    btnTextEl.addExtraButton((button) => {
      button.setIcon("reset").setTooltip(t("RESET_DEFAULT")).onClick(() => {
        settings.responseOptionBtnsText[algo][ind] = DEFAULT_responseOptionBtnsText[algo][ind];
        plugin.savePluginData();
        addResponseButtonTextSetting(containerEl, plugin);
      });
    });
  });
}

